when CLIENT_ACCEPTED {
  if { [IP::addr [IP::client_addr] eq $specific_ip ]} {
    SSL::profile host1_profile
  } else {
    SSL::profile ssl_profile2
  }
}

when HTTP_REQUEST {
  SSL::renegotiate
}

when SERVER_CONNECTED {
  if {[LB::server port] == 443 } {
    SSL::profile serverssl_profile
  } else {
    SSL::disable
  }
}
